#include "cpm22/memory_editor.hpp"
#include <algorithm>
#include <cctype>
#include <fstream>
#include <iomanip>
#include <sstream>
#include <system_error>
#include <vector>
namespace cpm22 { namespace {
std::string trim(std::string s){auto a=s.find_first_not_of(" \t\r\n");if(a==s.npos)return {};return s.substr(a,s.find_last_not_of(" \t\r\n")-a+1);}
std::string upper(std::string s){for(char& c:s)c=static_cast<char>(std::toupper(static_cast<unsigned char>(c)));return s;}
bool num(std::string s,std::size_t& v){try{if(s.empty())return false;std::size_t n=0;int b=s.size()>2&&s[0]=='0'&&(s[1]=='x'||s[1]=='X')?16:10;auto x=std::stoull(s,&n,b);if(n!=s.size())return false;v=static_cast<std::size_t>(x);return true;}catch(...){return false;}}
std::string hx(std::size_t n,int width){std::ostringstream o;o<<std::uppercase<<std::hex<<std::setw(width)<<std::setfill('0')<<n;return o.str();}
}
MemoryEditor::MemoryEditor(Memory&m,Bdos&d,BiosConsole&b,std::filesystem::path p):memory_(m),bdos_(d),bios_(b),settings_path_(std::move(p)){load_options();}
void MemoryEditor::load_options(){std::ifstream f(settings_path_);std::string l;while(std::getline(f,l)){auto p=l.find('=');if(p==l.npos)continue;auto k=upper(trim(l.substr(0,p))),v=upper(trim(l.substr(p+1)));if(k=="ROWS"&&(v=="8"||v=="16"))options_.bytes_per_row=static_cast<std::size_t>(std::stoul(v));else if(k=="ASCII")options_.show_ascii=v=="ON"||v=="TRUE";else if(k=="HEADER")options_.show_header=v=="ON"||v=="TRUE";else if(k=="COLOR"){options_.color=v!="OFF";options_.color_name=v;}}}
bool MemoryEditor::save_options(std::string&e)const{std::error_code ec;std::filesystem::create_directories(settings_path_.parent_path(),ec);if(ec){e=ec.message();return false;}std::ofstream f(settings_path_);if(!f){e="Cannot save memory options.";return false;}f<<"ROWS="<<options_.bytes_per_row<<"\nASCII="<<(options_.show_ascii?"ON":"OFF")<<"\nHEADER="<<(options_.show_header?"ON":"OFF")<<"\nCOLOR="<<(options_.color?options_.color_name:"OFF")<<"\n";return static_cast<bool>(f);}
std::string MemoryEditor::prefix()const{if(!options_.color)return {};auto c=upper(options_.color_name);if(c=="AMBER"||c=="YELLOW")return "\x1b[33m";if(c=="WHITE")return "\x1b[37m";if(c=="BLUE")return "\x1b[34m";if(c=="CYAN")return "\x1b[36m";return "\x1b[32m";}
std::string MemoryEditor::reset()const{return options_.color?"\x1b[0m":"";}
void MemoryEditor::display(std::size_t a,std::size_t rows){if(a>=Memory::capacity){bios_.write("Address must be 0000..FFFF.\n");return;}rows=std::min(rows,(Memory::capacity-a+options_.bytes_per_row-1)/options_.bytes_per_row);auto p=prefix(),r=reset();if(options_.show_header){std::ostringstream h;h<<p<<"ADDR ";for(std::size_t i=0;i<options_.bytes_per_row;++i)h<<std::uppercase<<std::hex<<std::setw(2)<<std::setfill('0')<<i<<' ';if(options_.show_ascii)h<<" ASCII";h<<r<<"\n";bios_.write(h.str());}
for(std::size_t y=0;y<rows;++y){auto base=a+y*options_.bytes_per_row;std::ostringstream o;o<<p<<hx(base,4)<<" ";std::string ascii;for(std::size_t x=0;x<options_.bytes_per_row;++x){auto at=base+x;if(at>=Memory::capacity){o<<"   ";ascii+=' ';continue;}auto b=*memory_.read(at);o<<hx(b,2)<<' ';ascii+=b>=32&&b<=126?static_cast<char>(b):'.';}if(options_.show_ascii)o<<" |"<<ascii<<'|';o<<r<<"\n";bios_.write(o.str());}}
void MemoryEditor::options(){bios_.write("Options: ROWS 8|16, ASCII ON|OFF, COLOR OFF|GREEN|AMBER|WHITE|BLUE|CYAN, HEADER ON|OFF, SAVE, EXIT\n");std::string l;while(bios_.write("options> "),bios_.read_line(l)){std::istringstream in(l);std::string k,v;in>>k>>v;k=upper(k);v=upper(v);if(k=="EXIT"||k=="BACK")return;if(k=="SAVE"){std::string e;bios_.write(save_options(e)?"Options saved.\n":e+"\n");continue;}if(k=="ROWS"&&(v=="8"||v=="16"))options_.bytes_per_row=static_cast<std::size_t>(std::stoul(v));else if(k=="ASCII"&&(v=="ON"||v=="OFF"))options_.show_ascii=v=="ON";else if(k=="HEADER"&&(v=="ON"||v=="OFF"))options_.show_header=v=="ON";else if(k=="COLOR"&&(v=="OFF"||v=="GREEN"||v=="AMBER"||v=="WHITE"||v=="BLUE"||v=="CYAN")){options_.color=v!="OFF";options_.color_name=v;}else{bios_.write("Invalid option.\n");continue;}bios_.write("Changed in memory; use SAVE to persist.\n");}}
int MemoryEditor::edit(std::size_t a){if(a>=Memory::capacity){bios_.write("Address must be 0000..FFFF.\n");return 1;}bios_.write("Memory spreadsheet editor: SHOW [addr] [rows], CELL addr byte, FILL addr count byte, OPTIONS, HELP, EXIT\n");std::string l;while(bios_.write("memedit["+hx(a,4)+"]> "),bios_.read_line(l)){std::istringstream in(l);std::string c,x,y,z;in>>c>>x>>y>>z;c=upper(c);if(c.empty())continue;if(c=="EXIT"||c=="BACK"||c=="QUIT")return 0;if(c=="HELP"){bios_.write("Byte values are decimal or 0x00..0xFF.\n");continue;}if(c=="OPTIONS"){options();continue;}if(c=="SHOW"){std::size_t start=a,n=16;if(!x.empty()&&!num(x,start)){bios_.write("Invalid address.\n");continue;}if(!y.empty()&&!num(y,n)){bios_.write("Invalid row count.\n");continue;}display(start,n);a=start;continue;}if(c=="CELL"||c=="SET"){std::size_t at{},v{};if(!num(x,at)||!num(y,v)||at>=Memory::capacity||v>255){bios_.write("Usage: CELL address byte\n");continue;}memory_.write(at,static_cast<std::uint8_t>(v));a=at-(at%options_.bytes_per_row);display(a,1);continue;}if(c=="FILL"){std::size_t at{},n{},v{};if(!num(x,at)||!num(y,n)||!num(z,v)||v>255||!memory_.fill(at,n,static_cast<std::uint8_t>(v))){bios_.write("Usage: FILL address count byte; range must fit RAM.\n");continue;}display(at,std::min<std::size_t>(4,(n+options_.bytes_per_row-1)/options_.bytes_per_row));continue;}bios_.write("Unknown editor command.\n");}return 0;}
bool MemoryEditor::export_csv(std::string file,std::size_t a,std::size_t n,std::string&e){auto bytes=memory_.snapshot(a,n);if(!bytes){e="Memory range exceeds 64 KiB.";return false;}std::ostringstream o;o<<"address";for(std::size_t i=0;i<options_.bytes_per_row;++i)o<<",b"<<i;o<<",ascii\n";for(std::size_t p=0;p<bytes->size();p+=options_.bytes_per_row){o<<"0x"<<hx(a+p,4);std::string asc;for(std::size_t i=0;i<options_.bytes_per_row;++i){o<<',';if(p+i<bytes->size()){auto b=(*bytes)[p+i];o<<"0x"<<hx(b,2);asc+=b>=32&&b<=126?static_cast<char>(b):'.';}}o<<",\""<<asc<<"\"\n";}return bdos_.write_file(std::move(file),o.str(),e);}
bool MemoryEditor::import_csv(std::string file,std::string&e){auto data=bdos_.read_file(std::move(file),e);if(!data)return false;std::istringstream all(*data);std::string line;bool first=true;std::size_t ln=0;while(std::getline(all,line)){++ln;if(trim(line).empty())continue;if(first){first=false;if(upper(line).rfind("ADDRESS",0)==0)continue;}std::stringstream row(line);std::vector<std::string> cells;std::string cell;while(std::getline(row,cell,','))cells.push_back(trim(cell));std::size_t a{};if(cells.size()<2||!num(cells[0],a)){e="Malformed CSV address on row "+std::to_string(ln);return false;}for(std::size_t i=1;i<cells.size()&&i<=options_.bytes_per_row;++i){if(cells[i].empty())continue;std::size_t v{};if(!num(cells[i],v)||v>255||a+i-1>=Memory::capacity){e="Invalid byte cell on CSV row "+std::to_string(ln);return false;}memory_.write(a+i-1,static_cast<std::uint8_t>(v));}}return true;}
}
